#include "core/Engine.h"
#include "core/FactoryPresets.h"
#include <array>
#include <cmath>
#include <cstdio>
#include <memory>
#include <cstdlib>
using namespace cs80;
int count=0;
void check(bool x,const char* m){++count;if(!x){std::fprintf(stderr,"FAIL %s\n",m);std::exit(1);}}
int main(){
 for(int rank=0;rank<2;++rank){
  auto changed=std::make_unique<Engine>(),fixed=std::make_unique<Engine>();
  ParamValues p;p[P_sourcePerformance]=1;p[P_analogNoise]=p[P_drift]=p[P_voiceDispersion]=p[P_chorusOn]=0;p[P_detune]=p[P_kasScanTiming]=0;p[P_mix]=(float)rank;p[bodyParam(rank,0)]=(float)body::oboe;p[bodyParam(rank,1)]=1;p[bodySizeParam(rank)]=1;
  std::array<float,512>a{},b{};
  for(auto*e:{changed.get(),fixed.get()}){e->setParams(p);e->prepare(48000);e->noteOn(60,100.0f/127);e->render(a.data(),64);}
  p[bodySizeParam(rank)]=2;changed->setParams(p);
  for(bool next:{false,true}){double delta=0,energy=0;bool finite=true;
   if(next){changed->noteOn(65,100.0f/127);fixed->noteOn(65,100.0f/127);}
   for(int block=0;block<8;++block){changed->render(a.data(),256);fixed->render(b.data(),256);for(size_t i=0;i<a.size();++i){finite=finite&&std::isfinite(a[i])&&std::isfinite(b[i]);delta+=(a[i]-b[i])*(a[i]-b[i]);energy+=a[i]*a[i]+b[i]*b[i];}}
   std::printf("rank%d next%d delta %.12g energy %.12g ratio %.12g\n",rank,next,delta,energy,delta/energy);
   check(finite&&energy>1e-8,"finite audible fixture");check(next?delta>1e-7*energy:delta==0,"next-note geometry capture");
  }
 }
 for(int ch=0;ch<2;++ch)for(int tone=0;tone<11;++tone){ParamValues p;p[bodySizeParam(ch)]=2.2f;p[bodySizeParam(1-ch)]=.6f;p[bodyParam(ch,0)]=(float)body::oboe;p[bodyParam(ch,1)]=1;applyHardwareTone(p,ch,tone);check(p[bodySizeParam(ch)]==1,"tab clears selected size");check(p[bodySizeParam(1-ch)]==.6f,"tab preserves other size");}
 constexpr const char* source[]={"Chamber Strings","PWM Strings","Brass Swell II","Horn Section","Analog Bass","Clavichord II","Harpsichord II","Reed Organ","Guitar II","Funky Pluck II","Funky Pluck I"};
 const auto&o=originalLibrary();const auto&c=curatedLibrary();for(int t=0;t<11;++t){const FactoryPreset*base=nullptr;for(const auto&v:c)if(v.name==source[t])base=&v;check(base!=nullptr,"source found");for(int rank=0;rank<2;++rank)check(o[2*t+1].values[bodySizeParam(rank)]==base->values[bodySizeParam(1-rank)],"rowII swaps both captured sizes");}
 std::printf("PASS %d core compatibility assertions\n",count);
}
